// ---------- ABOUT ----------
page({ file: 'about.html', a: 'about', title: 'Our Story', desc: 'The story of Rajvastra, three generations of curating India’s finest yarns and fabrics.', body: `${crumb('Our Story', 'oldLooms2')}
<section class="about-section-3 fix section-padding pb-0"><div class="container"><div class="about-wrapper-3"><div class="section-title-area"><div class="section-title"><p class="sub-title wow fadeInUp">Our Heritage<span class="line-1"></span></p><h2 class="char-animation">Three Generations. One Thread.</h2></div>
<div class="about-text-items"><div class="text-box"><h3 class="wow fadeInUp">Founded in Surat in 1987, Rajvastra began as a small yarn trading house.</h3><p class="mb-0 wow fadeInUp">Today we run spinning, dyeing and finishing units and work with 14 handloom clusters. Our promise is simple: exceptional material, honest provenance, and fair rewards for the hands that make it.</p></div><div class="about-btn wow fadeInUp"><a href="contact.html" class="theme-btn theme-two">Talk to Us <i class="fa-solid fa-arrow-right"></i></a></div></div></div>
<div class="about-image fix wow fadeInUp"><img data-speed=".8" src="${u('oldLooms3', 2580, 1086)}" alt="Rows of looms producing fabric"></div></div></div></section>
${featureGrid('What Drives Us', 'Mission, Vision & Values', [['fa-bullseye-arrow', 'Our Mission', 'To bring India’s finest yarns and fabrics to the world’s designers, with honest provenance and fair rewards for makers.'], ['fa-eye', 'Our Vision', 'A global textile house where heritage craft and modern quality standards sit side by side.'], ['fa-handshake', 'Our Values', 'Integrity, craftsmanship, transparency and long-term partnerships, in every order and every relationship.']], 'section-bg')}
<section class="counter-section counter-two fix pb-0"><div class="container"><div class="counter-content-area"><div class="row g-4">${[['38', '+', 'Years of heritage'], ['850', 'k+', 'Metres woven monthly'], ['1200', '+', 'Artisan families'], ['30', '+', 'Countries served']].map(c => `<div class="col-lg-3 col-sm-6 wow fadeInUp"><div class="counter-items counter-two"><div class="counter-box"><h2><span class="count">${c[0]}</span>${c[1]}</h2><p>${c[2]}</p></div></div></div>`).join('')}</div></div></div></section>
<section class="team-section section-padding section-bg fix"><div class="container">${title('Our Craft Clusters', 'Where Your Fabric Is Born', 'center')}<div class="row">${[['Varanasi, Uttar Pradesh', 'Banarasi brocade and silk', 'weaverMan', 'fabric-banarasi'], ['Phulia, West Bengal', 'Mulmul and jamdani', 'womanLoom2', 'fabric-handloom-cotton'], ['Bagru, Rajasthan', 'Block print and indigo', 'indigoHang', 'fabric-block-print'], ['Surat, Gujarat', 'Dyeing, finishing and quality control', 'machineSpools', 'collections']].map((c, i) => `<div class="col-xl-3 col-lg-4 col-md-6 wow fadeInUp" data-wow-delay="${0.2 + i * 0.2}s"><div class="team-card-item"><div class="team-image"><img src="${u(c[2], 600, 700)}" alt="${c[0]}"><img src="${u(c[2], 600, 700)}" alt="${c[0]}"></div><div class="team-content"><h3><a href="${c[3]}.html">${c[0]}</a></h3><p>${c[1]}</p></div></div></div>`).join('')}</div></div></section>
${timeline([['1987', 'A yarn trading house is born', 'Rajvastra opens in Surat, supplying cotton yarn to local mills.'], ['1999', 'Dye house & silk reeling', 'We add in-house dyeing and begin direct partnerships with silk reeling units.'], ['2008', 'Handloom clusters join', 'Long-term programmes begin with weavers in Varanasi, Phulia and Bagru.'], ['2016', 'Export desk opens', 'Dedicated team for private label, documentation and global logistics.'], ['2024', 'Natural dye & organic range', 'GOTS-certified cotton and natural indigo lines launched.'], ['2026', '2,000+ clients in 30 countries', 'Designers, boutiques and mills return season after season.']])}
${featureGrid('Sustainability', 'Good for People and the Planet', PROMISE)}
${split('A Note From Our Founder', 'Cloth Is Memory. We Simply Help It Travel.', ['“When my grandfather started trading yarn in Surat in 1987, he used to say that every thread carries the hands that made it. Four decades on, that is still how we work: we know the farms, the reelers, the dyers and the weaver families behind every metre we sell.', 'Our job is to protect that chain of craft and make it easy for designers anywhere in the world to use it. If we do that well, the cloth will speak for itself.”'], u('weaverMan', 1300, 1000), ['Direct relationships with 14 craft clusters', 'No middlemen between weaver and customer', 'A promise of honest provenance on every order'], false, ['contact.html', 'Meet the Team'])}
<section class="section-padding section-bg"><div class="container">${title('The Atelier Teams', 'The People Behind Every Order')}<div class="row g-4">${[['Design Desk', 'Trend forecasting, custom motif and colour development, and mood-board sourcing.', 'atelier2'], ['Dye House', 'Natural and azo-free dyeing, lab dips and shade matching in Surat.', 'hanks2'], ['Quality Lab', 'Count, strength, shrinkage and colour-fastness testing on every lot.', 'spoolsVert'], ['Export Desk', 'Documentation, private label, packing and worldwide logistics.', 'portDusk']].map((t, i) => `<div class="col-xl-3 col-md-6 wow fadeInUp" data-wow-delay="${i * 0.15}s"><div class="rv-card"><div class="rv-img" style="aspect-ratio:4/3"><img src="${u(t[2], 800, 600)}" alt="${t[0]}" loading="lazy"></div><div class="rv-body"><h3>${t[0]}</h3><p>${t[1]}</p></div></div></div>`).join('')}</div></div></section>
${steps('Our Craft Process', 'Six Stages of Quality, In Depth', [['Fibre sourcing', 'Cotton, silk, wool and zari are selected at origin and graded for length, purity and strength.'], ['Spinning & reeling', 'Fibre is spun or reeled to exact counts and twists on modern machines and traditional charkhas.'], ['Dyeing', 'Natural and azo-free dye lots are developed, lab-dipped and colour-matched in our Surat dye house.'], ['Weaving', 'Handloom and power-loom partners weave to our specifications, with design review at every stage.'], ['Finishing', 'Soft-washing, calendering and hand finishing give each fabric its signature handle.'], ['Inspection & packing', 'A three-gate quality check precedes export-grade packing and dispatch.']], '')}
${split('Who We Serve', 'Trusted by Designers, Mills and Fashion Houses', ['Our clients range from independent boutique designers to established fashion houses, textile mills, interior studios and export buyers in 30+ countries.', 'Whatever your scale, you get the same swatch standards, the same advisors and the same attention to detail.'], u('streetShops', 1300, 1000), ['Independent designers and bridal ateliers', 'Fashion houses and ready-to-wear brands', 'Interior designers and home-textile labels', 'Mills, traders and export importers'], true, ['wholesale.html', 'Explore Trade Programmes'])}
${featureGrid('Certifications & Standards', 'Quality You Can Document', CERTS, 'section-bg')}

<section class="section-padding"><div class="container"><div class="row g-4 align-items-center"><div class="col-lg-6"><div class="faq-content"><div class="section-title">${'<span class="sub-title">Questions</span><h2 class="char-animation">Everything You Need to Know</h2>'}</div></div>${faqAcc('abt', FAQ.slice(0, 4))}</div><div class="col-lg-6"><div class="faq-image fix"><img src="${u('atelier', 1146, 1244)}" alt="Design atelier"></div></div></div></div></section>
${ctaBand('Visit us or request a sample.', 'Our Surat studio welcomes designers by appointment.', 'Visit')}` });

